export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { isProcessableJobType, unsupportedJobTypeMessage } from '@/lib/jobs/jobRegistry'
import { checkProjectOwnership } from '@/lib/security/projectAccess'

// AUTO-GENERATED by api-row-sweep --apply — column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface BackgroundJobRow {
  id: string
  job_type: string
  status: string | null
  priority: number | null
  created_at: Date | null
  payload: unknown
  attempts: number | null
  max_attempts: number | null
  started_at: Date | null
  completed_at: Date | null
  error_message: string | null
  result: unknown | null
  updated_at: Date | null
}
export const POST = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const body = (ctx.body ?? {}) as {
    jobType: string
    projectId?: string
    payload?: Record<string, unknown>
    priority?: number
  }

  if (!body.jobType) {
    return NextResponse.json({ error: 'Missing jobType' }, { status: 400 })
  }

  if (!isProcessableJobType(body.jobType)) {
    return NextResponse.json({ error: unsupportedJobTypeMessage(body.jobType) }, { status: 422 })
  }

  const payloadProjectIdValue = body.payload?.project_id
  if (body.projectId !== undefined && (typeof body.projectId !== 'string' || !body.projectId.trim())) {
    return NextResponse.json({ error: 'Invalid projectId' }, { status: 400 })
  }
  if (payloadProjectIdValue !== undefined && (typeof payloadProjectIdValue !== 'string' || !payloadProjectIdValue.trim())) {
    return NextResponse.json({ error: 'Invalid payload.project_id' }, { status: 400 })
  }
  const payloadProjectId = typeof payloadProjectIdValue === 'string' ? payloadProjectIdValue : undefined
  if (body.projectId && payloadProjectId && body.projectId !== payloadProjectId) {
    return NextResponse.json({ error: 'Conflicting project identifiers' }, { status: 400 })
  }
  const projectId = body.projectId || payloadProjectId
  if (projectId && !(await checkProjectOwnership(ctx.userId, projectId))) {
    return NextResponse.json({ error: 'Project not found or inaccessible' }, { status: 403 })
  }

  // Build payload — merge projectId into payload if provided separately
  const payload = { ...(body.payload || {}) }
  if (projectId) {
    payload.project_id = projectId
  }
  // Thread userId so the worker can attribute audit entries correctly
  payload.userId = ctx.userId

  const priority = typeof body.priority === 'number'
    ? Math.max(0, Math.min(10, body.priority))
    : 5

  const { rows } = await db.query<BackgroundJobRow>(
    `INSERT INTO background_jobs (job_type, payload, priority, created_by)
     VALUES ($1, $2, $3, $4)
     RETURNING id, job_type, status, priority, created_at`,
    [body.jobType, JSON.stringify(payload), priority, ctx.userId]
  )

  return NextResponse.json({ success: true, job: rows[0], jobId: rows[0].id })
})

export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const { searchParams } = new URL(req.url)
  const status = searchParams.get('status')

  let query = 'SELECT * FROM background_jobs WHERE created_by = $1'
  const params: unknown[] = [ctx.userId]
  let paramIndex = 2

  if (status) {
    query += ` AND status = $${paramIndex++}`
    params.push(status)
  }

  query += ' ORDER BY priority DESC, created_at DESC LIMIT 50'

  const { rows } = await db.query<BackgroundJobRow>(query, params)
  return NextResponse.json({ jobs: rows })
})
